from pycompss.api.task import task
from pycompss.api.api import compss_wait_on


@task(returns=bool)
def task_contains(value, target):
    """Return True if value equals target (PyCOMPSs task)."""
    return value == target

@task(returns=bool)
def combine_results(result1, result2):
    """Combine two boolean results using logical OR (PyCOMPSs task)."""
    return result1 or result2

def main(x, y, target):
    """
    Check if the target value is in exactly one of the lists x or y.
    Use PyCOMPSs to compute in parallel.

    Example:

    input: x=[1, 8, 2, 6, 4, 6], target=3
    output: false

    input: x=[1, 8, 2, 6, 4, 6], target=8
    output: true
    """
    result_x = [task_contains(value, target) for value in x]
    result_y = [task_contains(value, target) for value in y]

    while len(result_x) > 1:
        for i in range(0, len(result_x), 2):
            if i + 1 < len(result_x):
                result_x[i // 2] = combine_results(result_x[i], result_x[i + 1])
            else:
                result_x[i // 2] = result_x[i]  
        result_x = result_x[: (len(result_x) + 1) // 2]

    while len(result_y) > 1:
        for i in range(0, len(result_y), 2):
            if i + 1 < len(result_y):
                result_y[i // 2] = combine_results(result_y[i], result_y[i + 1])
            else:
                result_y[i // 2] = result_y[i]  
        result_y = result_y[: (len(result_y) + 1) // 2]

    result_x = compss_wait_on(result_x)
    result_y = compss_wait_on(result_y)

    return result_x[0] != result_y[0]
